/****************************************************************************
 * drivers/video/esp32p4_jpeg_enc.c
 * ESP32-P4 Hardware JPEG Encoder V4L2 M2M Driver
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <debug.h>
#include <errno.h>
#include <sys/param.h>

#include <nuttx/kmalloc.h>
#include <nuttx/mutex.h>
#include <nuttx/video/v4l2_m2m.h>

#include "jpeg_encode.h"
#include "jpeg_types.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define JPEG_MAX_WIDTH     1024
#define JPEG_MAX_HEIGHT    768

/* Input: V4L2_PIX_FMT_RGB565 -> RGB565 2 bytes/pixel */
/* Output: V4L2_PIX_FMT_JPEG */

#define JPEG_OUT_BUF_SIZE(width, height)  ((width) * (height) * 2 / 2)
#define JPEG_CAP_BUF_SIZE(width, height)  ((width) * (height) * 2)

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct esp_jpeg_s
{
  /* V4L2 state */

  struct v4l2_format  out_fmt;
  struct v4l2_format  cap_fmt;
  bool                out_streaming;
  bool                cap_streaming;

  /* ESP-HAL JPEG engine */

  jpeg_encoder_handle_t  engine;

  /* Work queue for async encode */

  struct work_s       work;
  mutex_t             lock;
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static int jpeg_capture_enum_fmt(FAR void *priv, FAR struct v4l2_fmtdesc *f);
static int jpeg_output_enum_fmt(FAR void *priv, FAR struct v4l2_fmtdesc *f);
static int jpeg_capture_g_fmt(FAR void *priv, FAR struct v4l2_format *fmt);
static int jpeg_output_g_fmt(FAR void *priv, FAR struct v4l2_format *fmt);
static int jpeg_capture_s_fmt(FAR void *priv, FAR struct v4l2_format *fmt);
static int jpeg_output_s_fmt(FAR void *priv, FAR struct v4l2_format *fmt);
static int jpeg_capture_available(FAR void *priv);
static int jpeg_output_available(FAR void *priv);
static size_t jpeg_capture_g_bufsize(FAR void *priv);
static size_t jpeg_output_g_bufsize(FAR void *priv);
static size_t jpeg_capture_g_bufcnt(FAR void *priv);
static size_t jpeg_output_g_bufcnt(FAR void *priv);
static FAR void *jpeg_alloc_buf(FAR void *priv, size_t size);
static void jpeg_free_buf(FAR void *priv, FAR void *addr);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct codec_ops_s g_jpeg_ops =
{
  .capture_enum_fmt   = jpeg_capture_enum_fmt,
  .output_enum_fmt    = jpeg_output_enum_fmt,
  .capture_g_fmt      = jpeg_capture_g_fmt,
  .output_g_fmt       = jpeg_output_g_fmt,
  .capture_s_fmt      = jpeg_capture_s_fmt,
  .output_s_fmt       = jpeg_output_s_fmt,
  .capture_available  = jpeg_capture_available,
  .output_available   = jpeg_output_available,
  .capture_g_bufsize  = jpeg_capture_g_bufsize,
  .output_g_bufsize   = jpeg_output_g_bufsize,
  .capture_g_bufcnt   = jpeg_capture_g_bufcnt,
  .output_g_bufcnt    = jpeg_output_g_bufcnt,
  .alloc_buf          = jpeg_alloc_buf,
  .free_buf           = jpeg_free_buf,
};

/****************************************************************************
 * Private Functions - Format Enumeration
 ****************************************************************************/

static int jpeg_capture_enum_fmt(FAR void *priv,
                                  FAR struct v4l2_fmtdesc *f)
{
  if (f->index > 0) return -EINVAL;
  f->pixelformat = V4L2_PIX_FMT_JPEG;
  f->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  strlcpy((FAR char *)f->description, "JPEG", sizeof(f->description));
  return OK;
}

static int jpeg_output_enum_fmt(FAR void *priv,
                                 FAR struct v4l2_fmtdesc *f)
{
  if (f->index > 0) return -EINVAL;
  f->pixelformat = V4L2_PIX_FMT_RGB565;
  f->type = V4L2_BUF_TYPE_VIDEO_OUTPUT;
  strlcpy((FAR char *)f->description, "RGB565", sizeof(f->description));
  return OK;
}

/****************************************************************************
 * Private Functions - Get Format
 ****************************************************************************/

static int jpeg_capture_g_fmt(FAR void *priv, FAR struct v4l2_format *fmt)
{
  FAR struct esp_jpeg_s *ctx = priv;
  memcpy(fmt, &ctx->cap_fmt, sizeof(*fmt));
  return OK;
}

static int jpeg_output_g_fmt(FAR void *priv, FAR struct v4l2_format *fmt)
{
  FAR struct esp_jpeg_s *ctx = priv;
  memcpy(fmt, &ctx->out_fmt, sizeof(*fmt));
  return OK;
}

/****************************************************************************
 * Private Functions - Set Format
 ****************************************************************************/

static int jpeg_capture_s_fmt(FAR void *priv, FAR struct v4l2_format *fmt)
{
  FAR struct esp_jpeg_s *ctx = priv;

  if (fmt->type != V4L2_BUF_TYPE_VIDEO_CAPTURE)
    return -EINVAL;
  if (fmt->fmt.pix.pixelformat != V4L2_PIX_FMT_JPEG)
    return -EINVAL;

  /* JPEG encoder output: same dimensions as input */

  fmt->fmt.pix.width  = ctx->out_fmt.fmt.pix.width;
  fmt->fmt.pix.height = ctx->out_fmt.fmt.pix.height;
  fmt->fmt.pix.sizeimage = JPEG_CAP_BUF_SIZE(fmt->fmt.pix.width,
                                              fmt->fmt.pix.height);
  memcpy(&ctx->cap_fmt, fmt, sizeof(*fmt));
  return OK;
}

static int jpeg_output_s_fmt(FAR void *priv, FAR struct v4l2_format *fmt)
{
  FAR struct esp_jpeg_s *ctx = priv;

  if (fmt->type != V4L2_BUF_TYPE_VIDEO_OUTPUT)
    return -EINVAL;
  if (fmt->fmt.pix.pixelformat != V4L2_PIX_FMT_RGB565)
    return -EINVAL;

  /* Clamp to supported range */

  fmt->fmt.pix.width  = CLAMP(fmt->fmt.pix.width,  16, JPEG_MAX_WIDTH);
  fmt->fmt.pix.height = CLAMP(fmt->fmt.pix.height, 16, JPEG_MAX_HEIGHT);
  fmt->fmt.pix.sizeimage = JPEG_OUT_BUF_SIZE(fmt->fmt.pix.width,
                                              fmt->fmt.pix.height);
  memcpy(&ctx->out_fmt, fmt, sizeof(*fmt));
  return OK;
}

/****************************************************************************
 * Private Functions - Buffer Sizes
 ****************************************************************************/

static size_t jpeg_capture_g_bufsize(FAR void *priv)
{
  FAR struct esp_jpeg_s *ctx = priv;
  return JPEG_CAP_BUF_SIZE(ctx->out_fmt.fmt.pix.width,
                            ctx->out_fmt.fmt.pix.height);
}

static size_t jpeg_output_g_bufsize(FAR void *priv)
{
  FAR struct esp_jpeg_s *ctx = priv;
  return JPEG_OUT_BUF_SIZE(ctx->out_fmt.fmt.pix.width,
                            ctx->out_fmt.fmt.pix.height);
}

static size_t jpeg_capture_g_bufcnt(FAR void *priv)
{
  return 4; /* 4 output buffers (JPEG bitstream) */
}

static size_t jpeg_output_g_bufcnt(FAR void *priv)
{
  return 4; /* 4 input buffers (RGB565 frames) */
}

/****************************************************************************
 * Private Functions - Stream On/Off
 ****************************************************************************/

static int jpeg_capture_available(FAR void *priv)
{
  /* No async completion notification; encoder runs synchronously
   * in QBUF path. Return 0 to indicate poll-based operation. */
  return 0;
}

static int jpeg_output_available(FAR void *priv)
{
  return 0;
}

/****************************************************************************
 * Private Functions - Buffer Allocation
 ****************************************************************************/

static FAR void *jpeg_alloc_buf(FAR void *priv, size_t size)
{
  return kmm_malloc(size);
}

static void jpeg_free_buf(FAR void *priv, FAR void *addr)
{
  kmm_free(addr);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int esp32p4_jpeg_encoder_register(FAR const char *devpath)
{
  FAR struct esp_jpeg_s *ctx;
  FAR struct codec_s *codec;
  int ret;

  ctx = kmm_zalloc(sizeof(*ctx));
  if (!ctx) return -ENOMEM;

  codec = kmm_zalloc(sizeof(*codec));
  if (!codec) { kmm_free(ctx); return -ENOMEM; }

  codec->ops = &g_jpeg_ops;
  nxmutex_init(&ctx->lock);

  /* Set default output format: RGB565 1024x600 */

  ctx->out_fmt.type = V4L2_BUF_TYPE_VIDEO_OUTPUT;
  ctx->out_fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
  ctx->out_fmt.fmt.pix.width  = 1024;
  ctx->out_fmt.fmt.pix.height = 600;
  ctx->out_fmt.fmt.pix.sizeimage = JPEG_OUT_BUF_SIZE(1024, 600);

  /* Set default capture format: JPEG */

  ctx->cap_fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  ctx->cap_fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
  ctx->cap_fmt.fmt.pix.width  = 1024;
  ctx->cap_fmt.fmt.pix.height = 600;
  ctx->cap_fmt.fmt.pix.sizeimage = JPEG_CAP_BUF_SIZE(1024, 600);

  ret = codec_register(devpath, codec);
  if (ret < 0)
    {
      kmm_free(codec);
      kmm_free(ctx);
      return ret;
    }

  vinfo("ESP32-P4 JPEG encoder registered at %s (%dx%d)\n",
        devpath, 1024, 600);
  return OK;
}

